import hashlib
import bisect

class ConsistentHashRing:
    def __init__(self, nodes=None, vnodes=150):
        self.vnodes = vnodes
        self.ring = {}          # hash position -> physical node
        self.sorted_keys = []   # sorted hash positions
        for n in (nodes or []):
            self.add_node(n)

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

    def add_node(self, node: str):
        for i in range(self.vnodes):
            h = self._hash(f"{node}#{i}")
            self.ring[h] = node
            bisect.insort(self.sorted_keys, h)

    def remove_node(self, node: str):
        for i in range(self.vnodes):
            h = self._hash(f"{node}#{i}")
            del self.ring[h]
            self.sorted_keys.remove(h)

    def get_node(self, shard_key: str) -> str:
        if not self.ring:
            raise Exception("empty ring")
        h = self._hash(shard_key)
        idx = bisect.bisect(self.sorted_keys, h) % len(self.sorted_keys)
        return self.ring[self.sorted_keys[idx]]

ring = ConsistentHashRing(["shard0", "shard1", "shard2"])
print(ring.get_node("user:8675309"))  # deterministic node
ring.add_node("shard3")  # only ~1/4 of keys remap, not all

